{
  "schemaVersion": 1,
  "date": "2026-10-13",
  "interview": [
    {
      "id": "interview-01",
      "articleIds": [
        "2026-10-13-top-1"
      ],
      "question": "AIにパラメータ調整を任せるとき、どの処理を確実なルールとして残しますか。",
      "answer": "候補の有効性、試行の記録、停止条件は、決めたルールで処理します。記事では、エージェントが仮説を立て、エンジンが許容範囲と履歴を管理し、アダプターがdescribe、run、evaluateの三操作を担当します。比較はソースの初期値ではなく、デプロイ済みのベースラインから始めます。ただし設計提案なので、改善率が実証されたとは言えません。"
    },
    {
      "id": "interview-02",
      "articleIds": [
        "2026-10-13-top-2"
      ],
      "question": "多言語の画面で、言語の選択と翻訳漏れをどう管理しますか。",
      "answer": "言語を決める場所と、翻訳の確認を分けます。記事のPages RouterではlocaleDetectionをfalseにし、URLの言語を使います。辞書はtypeof templateでキーをそろえ、cloneInstanceは言語が変わるときだけ作ります。既存の言語なしURLも日本語で使えます。ただし型で分かるのはキーの漏れで、訳の自然さや表示崩れは別に確認が必要です。"
    },
    {
      "id": "interview-03",
      "articleIds": [
        "2026-10-13-top-3"
      ],
      "question": "新しい暗号機能を検証するとき、成功したと言える範囲をどう判断しますか。",
      "answer": "何を確認したかを、通信全体の安全性と分けて説明します。記事ではML-KEM-768をローカルのWorkersで動かし、32バイトの共有秘密が生成側と復元側で一致しました。webcrypto_modern_algorithmsの指定を外すと、同じ設定でもエラーになりました。これは鍵を共有する処理の確認で、通信内容の暗号化や本番の動作まで検証した結果ではありません。"
    },
    {
      "id": "interview-04",
      "articleIds": [
        "2026-10-13-top-4"
      ],
      "question": "開発ツールを一つにまとめれば、ビルド環境の問題も解決できますか。",
      "answer": "バージョンの管理と、ビルドに必要な環境は分けて考えます。記事ではpnpmがrust-toolchain.tomlを読み、Rustを用意しました。ただしネイティブのビルドはccがなく失敗し、wasm32-wasip1ではオフラインのビルドが通りました。依存はCargo.lockに残ります。この小さなLinuxの例を、そのまま別のOSやすべてのRustプロジェクトへ広げることはできません。"
    },
    {
      "id": "interview-05",
      "articleIds": [
        "2026-10-13-top-5"
      ],
      "question": "電話番号から顧客を自動で見つける機能は、どこまで確認すれば使えますか。",
      "answer": "関連付けの成功だけでなく、権限と反映されるタイミングも確認します。記事ではcustomer_data_viewerを追加し、通話終了後のInteractionにConsumerが結び付きました。ただし着信中は番号だけで、顧客のポップアップは確認できませんでした。同じ番号が二件あると先に作った方へ結び付いたため、重複時の扱いを決める必要があり、本人確認の代わりにもなりません。"
    }
  ],
  "review": [
    {
      "id": "review-01",
      "articleIds": [
        "2026-10-13-top-1",
        "2026-10-13-top-2"
      ],
      "question": "設定の基準を、どの情報から決めますか。",
      "points": {
        "zh": "调参从部署基线开始，前端从业务路径取得 locale；源码默认与浏览器设置不能替代实际对象。",
        "ja": "調整はデプロイ済みのベースライン、言語は業務のURLから決めます。初期値やブラウザ設定との違いを確認します。"
      }
    },
    {
      "id": "review-02",
      "articleIds": [
        "2026-10-13-top-3",
        "2026-10-13-top-4"
      ],
      "question": "小さな実験が通ったとき、どんな条件と失敗を一緒に記録しますか。",
      "points": {
        "zh": "ML-KEM 保留 Linux、Wrangler、flag 和未启用失败；Rust 保留版本、缓存、cc 缺失和仅简单 WASI 成功。",
        "ja": "ML-KEMはOS・Wrangler・フラグと省略時の失敗、Rustは版・キャッシュ・cc不足と小さなWASIの成功を記録します。"
      }
    },
    {
      "id": "review-03",
      "articleIds": [
        "2026-10-13-top-5"
      ],
      "question": "顧客の自動照合で、記録の完成と本人確認をどう分けますか。",
      "points": {
        "zh": "customer_data_viewer 与完成后 Consumer 链接有据；响铃无客户弹窗、同号码两记录限制了匹配，不能声称身份已验证。",
        "ja": "顧客参照権限と終了後のリンクを確認します。着信中の表示と番号重複には限界があり、照合を本人確認へ広げません。"
      }
    }
  ]
}
